CREATE TABLE pilot_metrics (id SERIAL PRIMARY KEY, workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, period VARCHAR(7) NOT NULL, setup_minutes INTEGER, manual_close_minutes INTEGER, ledgerly_close_minutes INTEGER, matched_count INTEGER NOT NULL DEFAULT 0, possible_count INTEGER NOT NULL DEFAULT 0, unmatched_count INTEGER NOT NULL DEFAULT 0, validation_failures INTEGER NOT NULL DEFAULT 0, corrections_required INTEGER NOT NULL DEFAULT 0, report_completed BOOLEAN NOT NULL DEFAULT FALSE, repeated_monthly_usage BOOLEAN NOT NULL DEFAULT FALSE, feedback TEXT, testimonial_permission BOOLEAN NOT NULL DEFAULT FALSE, readiness_checklist JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_pilot_metric_workspace_period UNIQUE(workspace_id,period), CONSTRAINT ck_pilot_metrics_nonnegative CHECK (COALESCE(setup_minutes,0) >= 0 AND COALESCE(manual_close_minutes,0) >= 0 AND COALESCE(ledgerly_close_minutes,0) >= 0 AND matched_count >= 0 AND possible_count >= 0 AND unmatched_count >= 0 AND validation_failures >= 0 AND corrections_required >= 0));
CREATE INDEX ix_pilot_metrics_workspace_id ON pilot_metrics(workspace_id); CREATE INDEX ix_pilot_metrics_period ON pilot_metrics(period);
